+  auto scope = manager.createPrewarmScope();
+  manager.recordText("A", 5, EpdFontFamily::REGULAR);
+  manager.recordText("B", 5, EpdFontFamily::BOLD);
+  manager.recordText("C", 5, EpdFontFamily::ITALIC);
+  scope.endScanAndPrewarm();
